[Form]
public class TFMLogicContextLookup extends FormRun
{
    TFMLogicBlock logicBlock;
    boolean         okButtonClicked;
    boolean         cancelButtonClicked;
    str             selectedID;
    Map             listIdx2FieldName;



}

public void closeSelect(str _selectString)
{
    if (!okButtonClicked)
    {
        super('');
    }
    super(_selectString ? _selectString : selectedID);
}

protected TFMFlowVariableName findVariableforBlock(TFMLogicBlock _block)
{
    SysDictClass    sdc = new SysDictClass(classIdGet(_block));
    SetEnumerator   meths = sdc.methods(true, false,true).getEnumerator();
    SysDictMethod   sdm;
    str             varCheck;
    while (meths.moveNext())
    {
        sdm = meths.current();
        if (sdm.returnTypeName() == extendedTypeStr(TFMFlowVariableName) && subStr(sdm.name(),1,4) == 'parm')
        {
            return sdc.callObject(sdm.name(),_block);
        }
        else if (sdm.returnTypeName() == extendedTypeStr(TFMFlowVariableContextLookupField) && subStr(sdm.name(),1,4) == 'parm')
        {
            varCheck = sdc.callObject(sdm.name(),_block);
            return (_block.inheritedValues().variableExists(varCheck) ? varCheck : '');
        }
    }
    return '';
}

public void init()
{
    TFMFlowVariableName                                 varName = this.findVariableforBlock(logicBlock);
    ClassName                                           lookupClass = logicBlock.inheritedValues().VariableLookupClass(varName);
    TFMLogicStepOperatorVariableContextLookupInterface  variableLookupContext = ClassName2id(lookupClass) ? new SysDictClass(className2Id(lookupClass)).makeObject() : null;
    Map                                                 contextMap = variableLookupContext ? variableLookupContext.lookupVariableContext() : null;
    SetEnumerator                                       sEnum = logicBlock.inheritedValues().fieldNamesEnumerator();
    MapEnumerator                                       mEnum = contextMap ? contextMap.getEnumerator() : null;
    super();
    listIdx2FieldName = new Map(Types::Integer, Types::String);
    while (sEnum.moveNext())
    {
        listIdx2FieldName.insert(FieldsListView.add(sEnum.current()), '{'+sEnum.current()+'}');
    }        
    while (mEnum && mEnum.moveNext())
    {

        TmpAotImport.TreeNodeName   = mEnum.currentKey();
        TmpAotImport.TreeNodePath   = mEnum.currentValue();

        TmpAotImport.doInsert();
    }
    this.initVarsTab();

    this.buildTree(logicBlock.inheritedValues());
}

protected void initVarsTab()
{
    SetEnumerator sEnum = logicBlock.inheritedValues().variableNames();
    varsTab.visible(varsTab.enabled(false));
    while (sEnum.moveNext())
    {            
        VariableTable.TreeNodeName  = sEnum.current();
        VariableTable.TreeNodePath  = sEnum.current();
        VariableTable.insert();
        varsTab.visible(varsTab.enabled(true));
    }
}

public TreeItemIdx buildTree(TFMLogicBlockDataInheritanceHandler _inheritance)
{
    MapEnumerator			mEnum;
    TreeItemIdx             idx;
    Map                     blocksNames = new Map(Types::String, Types::Integer);
    str                     blockName;
    str                     tblName;
    int                     blockIdx;
    str                     value;
    mEnum = _inheritance.prePostDatasourcesAvailable().getEnumerator();
    while (mEnum.moveNext())
    {
        value       = mEnum.currentValue();
        tblName     = TFMHelper::matchRegex(value, @'(.*?)\{');
        blockIdx    = blockIdx ? blockIdx : this.addTreeItemId("@TFM:HeaderDataSources",0,'',0);
        idx = this.addTreeItemId(tblName,0,'',blockIdx);

        this.buildSubTree(tblName,idx);
    }

    mEnum = _inheritance.dataSourcesAvailable().getEnumerator();
    while (mEnum.moveNext())
    {
        blockName   = TFMHelper::matchRegex(mEnum.currentValue(), @'\[(.*?)\]');
        tblName   = TFMHelper::matchRegex(mEnum.currentValue(), @'(.*?)\[');
        blockIdx = blocksNames.exists(blockName) ? blocksNames.lookup(blockName) : this.addTreeItemId(blockName,0,'',0);
        blocksNames.insert(blockName, blockIdx);
        idx = this.addTreeItemId(tblName,0,'',blockIdx);

        this.buildSubTree(tblName,idx);
    }
    dataTree.fontSize(20);
    dataTree.expand(blockIdx);

    return idx;
}

private TreeItemIdx addTreeItemId(Name _name, int64 _id, anytype _data, TreeItemIdx _parentIdx)
{
    FormTreeItem    formTreeItem = new FormTreeItem();
    TreeItemIdx     idx;

    //BP Deviation Documented
    formTreeItem.text(_name);
    formTreeItem.data(_data);

    idx = dataTree.addItem(_parentIdx, 0, formTreeItem);
    dataTree.expand(idx);

    return idx;
}

private void buildSubTree(TableName _tableName, TreeItemIdx _parentIdx)
{
    SysDictTable    sdt = new SysDictTable(tableName2Id(_tableName));
    Set             methods = sdt.methods(true,false,true);
    int             idx = this.addTreeItemId("@TFM:Fields",0,null,_parentIdx);
    SysDictMethod   sdm;
    SetEnumerator   sEnum = methods.getEnumerator();
    for (int i = 0; i < sdt.fieldCnt(TableScope::IncludeDerivedTables); i++)
    {
        this.addTreeItemId(sdt.fieldName(sdt.fieldCnt2Id(i, TableScope::IncludeDerivedTables)), 0,_tableName+'.'+sdt.fieldName(sdt.fieldCnt2Id(i, TableScope::IncludeDerivedTables)),idx);

    }
    idx = this.addTreeItemId("@TFM:Methods",0,null,_parentIdx);
    while (sEnum.moveNext())
    {
        sdm = sEnum.current();
        if (sdm.displayType() != DisplayFunctionType::Get)
        {
            continue;
        }
        this.addTreeItemId(sdm.name() + '()', 0,_tableName+'.'+sdm.name() + '()',idx);
    }


}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret;

    ret = super();
    selectedID = TmpAotImport.TreeNodeName;
    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret;

    ret = super();
    selectedID = VariableTable.TreeNodeName;
    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_Idx"></param>
/// <param name = "_Data"></param>
public void selectionChanged(int _Idx, anytype _Data)
{
    super(_Idx, _Data);
    selectedID = listIdx2FieldName.lookup(_Idx);
}

/// <summary>
///
/// </summary>
/// <param name = "_OldItem"></param>
/// <param name = "_NewItem"></param>
/// <param name = "_how"></param>
public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
{
    super(_OldItem, _NewItem, _how);
    selectedID = _NewItem.data() ? _NewItem.data() : '';
}

void clicked()
{
    TFMPageMenuItems record;
    TFMPageAdhocMenuItemsAdditionalProperties	additionalProps;
    MapEnumerator								mEnum;
    TFMPage										page;
    okButtonClicked = true;

    element.closeSelect(selectedID);
    super();
}

/// <summary>
///
/// </summary>
public void clicked()
{
    cancelButtonClicked = true;
    element.closeSelect('');
    super();

}
